{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-xSFDmu/src/address.js","content":"/**
 * Cell address parsing and ordering. Columns run A..Z then AA..ZZ (1..702);
 * rows are 1..999 (one to three digits). Addresses are read case-insensitively.
 */

const SHEET_ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/
const WORD_ADDRESS_RE = /^([A-Za-z]+)([0-9]*)$/

function colFromLetters(letters) {
  let col = 0
  for (const ch of letters) {
    col = col * 26 + (ch.toUpperCase().charCodeAt(0) - 64)
  }
  return col
}

/**
 * Parses a strict sheet-declaration address (as found at the start of an
 * input line). Returns null when the text is not a valid address.
 */
export function parseSheetAddress(text) {
  const m = SHEET_ADDRESS_RE.exec(text)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const row = Number(m[2])
  if (row < 1) return null
  const col = colFromLetters(letters)
  return { letters, row, col, key: `${letters}${row}` }
}

/**
 * Parses a formula "word" (letters followed by optional digits) as an
 * address attempt. Always returns letters/digits; `valid` tells whether it
 * names a cell inside the addressable range.
 */
export function parseWordAddress(word) {
  const m = WORD_ADDRESS_RE.exec(word)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const digits = m[2]
  const valid = letters.length <= 2 && digits.length >= 1 && digits.length <= 3 && Number(digits) >= 1
  if (!valid) return { valid: false, letters, digits }
  const row = Number(digits)
  const col = colFromLetters(letters)
  return { valid: true, letters, digits, row, col, key: `${letters}${row}` }
}

export function compareAddresses(a, b) {
  return a.col - b.col || a.row - b.row
}
"}

