{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-xSFDmu/src/values.js","content":"/**
 * The value type every formula and literal evaluates to: a number, text, a
 * boolean, or an error token.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const ERROR_TOKEN_SET = new Set(ERROR_TOKENS)

export function num(value) {
  return { type: 'number', value }
}

export function text(value) {
  return { type: 'text', value }
}

export function bool(value) {
  return { type: 'bool', value }
}

export function err(token) {
  return { type: 'error', value: token }
}

export const ERR_DIV0 = err('#DIV/0!')
export const ERR_REF = err('#REF!')
export const ERR_VALUE = err('#VALUE!')
export const ERR_CYCLE = err('#CYCLE!')
export const ERR_NAME = err('#NAME?')
export const ERR_GENERIC = err('#ERR!')

export function isErrorToken(text) {
  return ERROR_TOKEN_SET.has(text)
}

/** A literal cell content string (not starting with `=`) read as a value. */
export function literalToValue(content) {
  if (content === '') return num(0)
  if (isErrorToken(content)) return err(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  return text(content)
}

/** Rounds a finite number to ten significant digits. */
function roundToTenSigFigs(n) {
  if (n === 0) return 0
  return Number(n.toPrecision(10))
}

export function formatValue(value) {
  switch (value.type) {
    case 'number':
      return String(roundToTenSigFigs(value.value))
    case 'text':
      return value.value
    case 'bool':
      return value.value ? 'TRUE' : 'FALSE'
    case 'error':
      return value.value
    default:
      throw new Error(`unknown value type: ${value.type}`)
  }
}

/** Coerces a value to a number in an arithmetic position. */
export function coerceNumber(value) {
  if (value.type === 'number') return { ok: true, value: value.value }
  if (value.type === 'bool') return { ok: true, value: value.value ? 1 : 0 }
  return { ok: false }
}

/** Compares two values per the cross-type ordering rules. */
export function compareValues(a, b) {
  const rank = (v) => (v.type === 'number' ? 0 : v.type === 'text' ? 1 : 2)
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.type === 'number') return a.value - b.value
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  // bool: false below true
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}
"}

