{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-xSFDmu/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`). Spaces and
 * tabs may sit anywhere between tokens.
 */

export class LexError extends Error {}

const PUNCT_TWO = ['<=', '>=', '<>']
const PUNCT_ONE = ['(', ')', ':', ',', '^', '*', '/', '+', '-', '=', '<', '>']

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.' && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', value: Number(src.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(src[j])) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'WORD', value: src.slice(i, j) })
      i = j
      continue
    }
    const two = src.slice(i, i + 2)
    if (PUNCT_TWO.includes(two)) {
      tokens.push({ type: two, value: two })
      i += 2
      continue
    }
    if (PUNCT_ONE.includes(ch)) {
      tokens.push({ type: ch, value: ch })
      i++
      continue
    }
    throw new LexError(`unexpected character ${JSON.stringify(ch)}`)
  }
  tokens.push({ type: 'EOF', value: null })
  return tokens
}
"}

