const KNOWN_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

/** Parses (and caches) the formula AST for a cell's content, if it is one. */
function getFormulaAst(cell) {
  if (cell.astComputed) return cell.ast
  cell.astComputed = true
  if (cell.content.startsWith('=')) {
    try {
      cell.ast = parseFormula(cell.content.slice(1))
    } catch (e) {
      if (e instanceof ParseError) {
        cell.ast = null
      } else {
