 * Parses the raw sheet text into a map of declared cells, enforcing address
 * validity and no-duplicate-declaration rules.
 */

import { parseSheetAddress, compareAddresses } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/**
 * Returns `{ cells, order }` where `cells` maps address key to
 * `{ content, addr }` and `order` lists the keys in ascending column-then-row
 * order. Throws SheetError with a ready-to-print message on the first
 * invalid line.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    let j = 0
    while (j < stripped.length && stripped[j] !== ' ' && stripped[j] !== '\t') j++
    const addressText = stripped.slice(0, j)
    let k = j
    while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
    const content = stripped.slice(k)

    const addr = parseSheetAddress(addressText)
    if (!addr) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addressText}`)
    }
    if (cells.has(addr.key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${addr.key} is declared twice`)
    }
    cells.set(addr.key, { content, addr, astComputed: false, ast: undefined })
  }

  const order = [...cells.values()].map((c) => c.addr).sort(compareAddresses).map((a) => a.key)
  return { cells, order }
}
"}

